{"script":"content = repo.read("logs/large.log")
lines = content.splitlines()

def digits_to_hash(s):
    out = []
    for ch in s.elems():
        if ch >= "0" and ch <= "9":
            out.append("#")
        else:
            out.append(ch)
    return "".join(out)

tmpl = {}
for l in lines:
    t = digits_to_hash(l)
    tmpl[t] = tmpl.get(t, 0) + 1
uniq = sorted(tmpl.items(), key=lambda x: -x[1])[:15]
tail = "\n".join(["%d: %s" % (i+1, lines[i]) for i in range(3590, 3602)])
result("TAIL:\n%s\n\nTEMPLATES:\n%s" % (tail, "\n".join(["%d x %s" % (c, t) for t, c in uniq])))
"}
